//! m2a: convert MIT format annotation files to AHA DB distribution tape
//! format (port of `convert/m2a.c`).
//!
//! The files generated by this program are in the format formerly used for
//! distribution of the AHA and MIT-BIH databases on half-inch 9-track
//! digital tape. It does *not* generate files in the format currently used
//! for distribution of the AHA database on floppy disk; `a2m` can perform
//! the reverse conversion, however.
//
// Copyright (C) 2001 George B. Moody (original C program, convert/m2a.c).
// Rust implementation part of wfdb-x, Reza Sameni, Oct 2026.
// Design decision (Reza Sameni, Oct 2026): no built-in sampling frequency,
// gain, ADC resolution or units. Values that the record or the user does not
// give are never assumed (the original package assumed 250 Hz, 200 adu/mV,
// 12 bits and millivolts), because a silently assumed value corrupts every
// result derived from it. See docs/DIVERGENCES.md.
// GNU General Public License, version 2 or later (see LICENSE).

use wfdbx::cstd;
use wfdbx::{ceprintf, csscanf, Anninfo, Annotation, WFDB_AHA_WRITE, WFDB_DEFFREQ, WFDB_READ};

const HELP_STRINGS: &[&[u8]] = &[
    b"usage: %s -r RECORD -a MIT-ANNOTATOR AHA-ANNOTATOR [ OPTIONS ... ]\n",
    b"where RECORD is the record name, MIT-ANNOTATOR is the annotator name",
    b"for the input annotation file, AHA-ANNOTATOR is the annotator name",
    b"for the output (AHA format) annotation file, and OPTIONS may include:",
    b" -F FREQ   sampling frequency, if the record header does not specify one",
    b" -h        print this usage summary",
    b" -s TIME   shift annotation times backwards by the specified TIME,",
    b"            and convert them to milliseconds",
];

/// wfdb-x: the lines of `HELP_STRINGS` added by wfdb-x, left out of the
/// help text of the original program (printed in legacy mode).
const WFDBX_HELP_LINES: &[&[u8]] =
    &[b" -F FREQ   sampling frequency, if the record header does not specify one"];

fn help(pname: &[u8]) {
    let legacy = wfdbx::wfdbx_get_legacy() != 0;
    ceprintf!(HELP_STRINGS[0], pname);
    for s in &HELP_STRINGS[1..] {
        if !(legacy && WFDBX_HELP_LINES.contains(s)) {
            ceprintf!(b"%s\n", s);
        }
    }
}

fn main() {
    let mut argv = cstd::args();
    let legacy = wfdbx::wfdbx_legacy_args(&mut argv) != 0; // wfdb-x: --legacy
    let argc = argv.len();
    let pname = cstd::prog_name(&argv[0]).to_vec();
    let mut ianame: Option<&[u8]> = None;
    let mut oaname: Option<&[u8]> = None;
    let mut record: Option<&[u8]> = None;
    let mut shift: Option<&[u8]> = None;
    let mut ffreq = 0.0f64; // -F (wfdb-x)
    let mut annot = Annotation::default();

    let mut i = 1;
    while i < argc {
        let a = &argv[i];
        if a.first() == Some(&b'-') {
            match a.get(1).copied().unwrap_or(0) {
                b'a' => {
                    // annotator names follow
                    i += 1;
                    if i + 1 >= argc {
                        ceprintf!(
                            b"%s: input and output annotator names must follow -a\n",
                            pname
                        );
                        cstd::exit(1);
                    }
                    ianame = Some(&argv[i]);
                    i += 1;
                    oaname = Some(&argv[i]);
                }
                b'F' if !legacy => {
                    // sampling frequency follows (wfdb-x)
                    i += 1;
                    if i >= argc || csscanf!(&argv[i], b"%lf", &mut ffreq) != 1 || ffreq <= 0.0 {
                        ceprintf!(b"%s: sampling frequency (> 0) must follow -F\n", pname);
                        cstd::exit(1);
                    }
                }
                b'h' => {
                    // help requested
                    help(&pname);
                    cstd::exit(1);
                }
                b'r' => {
                    // record name follows
                    i += 1;
                    if i >= argc {
                        ceprintf!(b"%s: record name must follow -r\n", pname);
                        cstd::exit(1);
                    }
                    record = Some(&argv[i]);
                }
                b's' => {
                    // shift follows
                    i += 1;
                    if i >= argc {
                        ceprintf!(b"%s: time shift must follow -s\n", pname);
                        cstd::exit(1);
                    }
                    shift = Some(&argv[i]);
                }
                _ => {
                    ceprintf!(b"%s: unrecognized option %s\n", pname, a);
                    cstd::exit(1);
                }
            }
        } else {
            ceprintf!(b"%s: unrecognized argument %s\n", pname, a);
            cstd::exit(1);
        }
        i += 1;
    }
    let (Some(ianame), Some(oaname), Some(record)) = (ianame, oaname, record) else {
        help(&pname);
        cstd::exit(1);
    };

    let afarray = [
        Anninfo {
            name: cstd::cstr(ianame).to_vec(),
            stat: WFDB_READ,
        },
        Anninfo {
            name: cstd::cstr(oaname).to_vec(),
            stat: WFDB_AHA_WRITE,
        },
    ];
    if wfdbx::annopen(record, &afarray, 2) < 0 {
        // open files
        cstd::exit(2);
    }
    match shift {
        None => {
            while wfdbx::getann(0, &mut annot) >= 0 {
                // copy annotations to end of data
                wfdbx::putann(0, &annot);
            }
        }
        Some(shift) => {
            // wfdb-x: no default sampling frequency (the C program assumed
            // 250 Hz if the record header did not specify one, as legacy
            // mode does); -F specifies one.
            if wfdbx::sampfreq(record) <= 0.0 {
                if legacy {
                    wfdbx::setsampfreq(WFDB_DEFFREQ);
                } else if ffreq > 0.0 {
                    wfdbx::setsampfreq(ffreq);
                } else {
                    ceprintf!(
                        b"%s: sampling frequency of record %s is not specified (use -F)\n",
                        pname,
                        record
                    );
                    cstd::exit(1);
                }
            }
            // milliseconds per sample interval
            let mssi = 1000.0 / wfdbx::strtim("1") as f64;
            let dt = wfdbx::strtim(shift);
            while wfdbx::getann(0, &mut annot) >= 0 {
                if annot.time >= dt {
                    annot.time = cstd::d2l((annot.time.wrapping_sub(dt)) as f64 * mssi);
                    wfdbx::putann(0, &annot);
                }
            }
        }
    }

    wfdbx::wfdbquit();
    cstd::exit(0);
}
